//! Differential test for `crs::transform`: coordinate pairs between supported CRSs (WGS84, Web
//! Mercator, UTM 33N, 18N, 55S, Lambert-93, Conus Albers, OSGB36 and the British National Grid),
//! with PROJ's results from rasterio (GDAL 3.12). The source point is PROJ's forward projection
//! of a geographic point, so each row isolates the CRS-to-CRS conversion. Generated by
//! `generate_transform_reference.py` next to the data.
//!
//! The OSGB36 rows use the Helmert transform, which PROJ also uses here because no OSTN15 grid
//! is installed. PROJ's Helmert and ours agree to about a millimetre. The larger tolerance on
//! those rows is the Transverse Mercator series, which is about 3.5 mm off at 4° from the
//! central meridian and grows with distance from it.

use std::path::PathBuf;

use tpt_gis_core::crs::transform;
use tpt_gis_core::epsg;
use tpt_gis_core::PlanarPoint;

/// The British National Grid and OSGB36 codes, whose rows get the wider tolerance.
const OSGB_CODES: [u32; 2] = [4277, 27700];

#[test]
fn transforms_agree_with_proj() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/proj_transform.csv");
    let text = std::fs::read_to_string(path).unwrap();
    let mut worst = (0.0_f64, String::new());
    let mut worst_osgb = (0.0_f64, String::new());
    let mut checked = 0;
    for line in text.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()) {
        let f: Vec<&str> = line.split(';').collect();
        let src: u32 = f[0].parse().unwrap();
        let dst: u32 = f[1].parse().unwrap();
        let num = |i: usize| f[i].parse::<f64>().unwrap();
        let from = epsg::lookup(src).expect("source CRS");
        let to = epsg::lookup(dst).expect("target CRS");
        let got = transform(PlanarPoint::new(num(2), num(3)), from, to);
        let err = (got.x - num(4)).hypot(got.y - num(5));
        let slot = if OSGB_CODES.contains(&src) || OSGB_CODES.contains(&dst) {
            &mut worst_osgb
        } else {
            &mut worst
        };
        if err > slot.0 {
            *slot = (err, line.to_string());
        }
        checked += 1;
    }
    println!(
        "{checked} transforms, worst error {:.9} m (OSGB rows {:.9} m): {}",
        worst.0, worst_osgb.0, worst.1
    );
    assert!(checked > 200, "only {checked} rows");
    // Measured worst case 0.96 mm (UTM's series against PROJ's); bound with headroom.
    assert!(worst.0 < 2e-3, "worst error {} m on {}", worst.0, worst.1);
    // Measured worst case 9.97 mm, about 4° from the central meridian (the series error).
    assert!(worst_osgb.0 < 2e-2, "OSGB worst error {} m on {}", worst_osgb.0, worst_osgb.1);
}
